 TabPage subtitlePage;FlowLayoutPanel subtitleOptions,subtitleButtons;DataGridView subtitleJobs=new DataGridView(),subtitleGrid=new DataGridView();ComboBox subtitleModel=new ComboBox(),subtitleDevice=new ComboBox(),subtitleStyle=new ComboBox();NumericUpDown subtitleTrack=new NumericUpDown();Label subtitleInfo=new Label();CheckBox subtitleSkip=new CheckBox();readonly List<SubtitleJob> subtitleQueue=new List<SubtitleJob>();SubtitleProcess subtitleProcess;SubtitleJob subtitleEditing;bool subtitleLoading;
 string SubtitleHome{get{return Path.Combine(stateDir,"subtitles");}}string SubtitleCache{get{return Path.Combine(SubtitleHome,"projects");}}
