 string SubtitleScript(string file){return Path.Combine(root,"source","asr",file);}string SubtitleModelKey{get{return subtitleModel.SelectedIndex==1?"distil-large-v3":"large-v3";}}string SubtitleDeviceKey{get{return subtitleDevice.SelectedIndex==1?"gpu":subtitleDevice.SelectedIndex==2?"cpu":"auto";}}
