  layout.Controls.Add(new Label{Text="Lấy lời nói tiếng Anh và căn phụ đề theo âm thanh gốc. Nhiều file chạy lần lượt; SRT lưu cạnh MP4/MP3.\nCài bộ phụ đề một lần khi có mạng, sau đó dùng offline. Tự đối chiếu từ lặp / dấu câu. Vàng: cần nghe lại; xanh nhạt: đã xử lý hoặc đã duyệt.",Dock=DockStyle.Fill,ForeColor=muted},0,0);
  subtitleOptions=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true};layout.Controls.Add(subtitleOptions,0,1);subtitleOptions.Controls.Add(Btn("Thêm MP4 / MP3",(s,e)=>{if(busy)return;using(var d=new OpenFileDialog{Filter="Âm thanh / video|*.mp4;*.mp3;*.wav;*.m4a;*.mov;*.mkv",Multiselect=true})if(d.ShowDialog()==DialogResult.OK)AddSubtitleFiles(d.FileNames);}));
  subtitleModel.DropDownStyle=subtitleDevice.DropDownStyle=subtitleStyle.DropDownStyle=ComboBoxStyle.DropDownList;subtitleModel.Width=230;subtitleModel.Items.AddRange(new object[]{"Chất lượng · Whisper large-v3","Nhanh · Distil large-v3 English"});subtitleModel.SelectedIndex=0;subtitleOptions.Controls.Add(subtitleModel);subtitleDevice.Width=150;subtitleDevice.Items.AddRange(new object[]{"Auto · GPU / CPU","NVIDIA GPU","CPU"});subtitleDevice.SelectedIndex=0;subtitleOptions.Controls.Add(subtitleDevice);
  subtitleOptions.Controls.Add(new Label{Text="Luồng tiếng:",AutoSize=true,Padding=new Padding(0,7,0,0)});subtitleTrack.Minimum=1;subtitleTrack.Maximum=32;subtitleTrack.Value=1;subtitleTrack.Width=48;subtitleTrack.DecimalPlaces=0;subtitleOptions.Controls.Add(subtitleTrack);subtitleStyle.Width=175;subtitleStyle.DropDownWidth=270;subtitleStyle.Items.AddRange(new object[]{"Câu tự nhiên · tối đa 2 dòng","Ngắn · phù hợp TikTok"});subtitleStyle.SelectedIndex=0;subtitleOptions.Controls.Add(subtitleStyle);
  subtitleOptions.Controls.Add(Btn("Cài bộ phụ đề",async(s,e)=>await SetupSubtitles()));subtitleOptions.Controls.Add(Btn("Kiểm tra bộ phụ đề",async(s,e)=>await ProbeSubtitles()));subtitleOptions.Controls.Add(Btn("Bỏ file đã chọn",(s,e)=>{if(busy||subtitleJobs.CurrentRow==null)return;var j=subtitleQueue[subtitleJobs.CurrentRow.Index];subtitleQueue.Remove(j);if(subtitleEditing==j){subtitleEditing=null;subtitleGrid.Rows.Clear();}RefreshSubtitleJobs();}));subtitleOptions.Controls.Add(Btn("Gắn / bỏ TXT lời gốc",(s,e)=>AttachSubtitleText()));subtitleSkip.Text="Bỏ qua file đã xong";subtitleSkip.Checked=true;subtitleSkip.AutoSize=true;subtitleOptions.Controls.Add(subtitleSkip);
  var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,SplitterWidth=7,Panel1MinSize=70,Panel2MinSize=90};layout.Controls.Add(split,0,2);SetupSubtitleGrid(subtitleJobs);subtitleJobs.ReadOnly=true;foreach(var col in new[]{"File nguồn","Luồng","Trạng thái","Kết quả / lỗi"})subtitleJobs.Columns.Add(col,col);subtitleJobs.Columns[0].Width=280;subtitleJobs.Columns[1].Width=55;subtitleJobs.Columns[2].Width=160;subtitleJobs.Columns[3].AutoSizeMode=DataGridViewAutoSizeColumnMode.Fill;split.Panel1.Controls.Add(subtitleJobs);subtitleJobs.SelectionChanged+=(s,e)=>SelectSubtitleJob();
  SetupSubtitleGrid(subtitleGrid);foreach(var col in new[]{"#","Bắt đầu","Kết thúc","Lời nói","Kiểm tra / xử lý"})subtitleGrid.Columns.Add(col,col);subtitleGrid.Columns[0].Width=40;subtitleGrid.Columns[1].Width=112;subtitleGrid.Columns[2].Width=112;subtitleGrid.Columns[3].AutoSizeMode=DataGridViewAutoSizeColumnMode.Fill;subtitleGrid.Columns[4].Width=240;subtitleGrid.Columns[0].ReadOnly=subtitleGrid.Columns[4].ReadOnly=true;split.Panel2.Controls.Add(subtitleGrid);subtitleGrid.CellEndEdit+=(s,e)=>SaveSubtitleEdits();
  subtitleButtons=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true};layout.Controls.Add(subtitleButtons,0,3);subtitleButtons.Controls.Add(Btn("TẠO SRT HÀNG ĐỢI",async(s,e)=>await RunSubtitleQueue(),true));subtitleButtons.Controls.Add(Btn("▶ Nghe đoạn",async(s,e)=>await ListenSubtitle()));subtitleButtons.Controls.Add(Btn("Căn lại lời đã sửa",async(s,e)=>await RealignSubtitle()));subtitleButtons.Controls.Add(Btn("Đã nghe / duyệt khối",(s,e)=>ApproveSubtitleCue()));subtitleButtons.Controls.Add(Btn("Xuất SRT",(s,e)=>ExportSubtitleEdits()));subtitleButtons.Controls.Add(Btn("Mở kết quả",(s,e)=>{if(subtitleEditing!=null)OpenResult(subtitleEditing.Output);}));
