 }
 void SetupSubtitleGrid(DataGridView g){g.Dock=DockStyle.Fill;g.BackgroundColor=Color.White;g.RowHeadersVisible=false;g.AllowUserToAddRows=false;g.AllowUserToDeleteRows=false;g.MultiSelect=false;g.SelectionMode=DataGridViewSelectionMode.FullRowSelect;g.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.DisplayedCells;g.DefaultCellStyle.WrapMode=DataGridViewTriState.True;g.DefaultCellStyle.ForeColor=navy;g.DefaultCellStyle.SelectionForeColor=Color.White;g.RowTemplate.MinimumHeight=34;}
 bool IsSubtitleMedia(string path){return new[]{".mp4",".mp3",".wav",".m4a",".mov",".mkv"}.Contains(Path.GetExtension(path).ToLowerInvariant());}
 void DropInputs(string[] paths){if(busy)return;var media=paths.Where(IsSubtitleMedia).ToArray();var text=paths.Where(p=>!IsSubtitleMedia(p)).ToArray();if(text.Length>1)AddFiles(text);else if(text.Length==1)LoadFile(text[0]);if(media.Length>0)AddSubtitleFiles(media);}
 string SubtitleSourceStamp(string path){try{var f=new FileInfo(path);return f.Length+":"+f.LastWriteTimeUtc.Ticks;}catch{return "missing";}}
 void AddSubtitleFiles(IEnumerable<string> paths){if(busy)return;Directory.CreateDirectory(SubtitleCache);foreach(string path in paths){if(subtitleQueue.Count>=500)break;string full=Path.GetFullPath(path);if(!IsSubtitleMedia(full)||!File.Exists(full)||subtitleQueue.Any(j=>j.Input.Equals(full,StringComparison.OrdinalIgnoreCase)&&j.Track==(int)subtitleTrack.Value-1))continue;subtitleQueue.Add(new SubtitleJob{Input=full,SourceStamp=SubtitleSourceStamp(full),Track=(int)subtitleTrack.Value-1,Result=Path.Combine(SubtitleCache,Guid.NewGuid().ToString("N")+".xml")});}RefreshSubtitleJobs();tabs.SelectedTab=subtitlePage;}
 void RefreshSubtitleJobs(){if(subtitleJobs.Columns.Count==0||IsDisposed||Disposing)return;subtitleLoading=true;int index=subtitleJobs.CurrentRow==null?0:subtitleJobs.CurrentRow.Index;try{subtitleJobs.Rows.Clear();foreach(var j in subtitleQueue){int row=subtitleJobs.Rows.Add(Path.GetFileName(j.Input),j.Track+1,j.State,String.IsNullOrEmpty(j.Error)?j.Output:j.Error);subtitleJobs.Rows[row].Cells[0].ToolTipText=j.Input+(String.IsNullOrEmpty(j.Reference)?"":"\nTXT: "+j.Reference);if(j.State=="Lỗi")subtitleJobs.Rows[row].DefaultCellStyle.BackColor=Color.MistyRose;else if(j.Document!=null&&j.Document.ReviewCount>0)subtitleJobs.Rows[row].DefaultCellStyle.BackColor=Color.LemonChiffon;}if(subtitleJobs.Rows.Count>0)subtitleJobs.CurrentCell=subtitleJobs.Rows[Math.Min(index,subtitleJobs.Rows.Count-1)].Cells[0];}finally{subtitleLoading=false;}SaveSubtitleQueue();SelectSubtitleJob();}
 void SelectSubtitleJob(){if(subtitleLoading||IsDisposed||Disposing||subtitleGrid.IsDisposed||subtitleGrid.Disposing||subtitleGrid.Columns.Count==0)return;subtitleEditing=subtitleJobs.CurrentRow==null?null:subtitleQueue[subtitleJobs.CurrentRow.Index];FillSubtitleGrid();}
 void FillSubtitleGrid(){if(IsDisposed||Disposing||subtitleGrid.IsDisposed||subtitleGrid.Disposing||subtitleGrid.Columns.Count==0)return;subtitleLoading=true;try{subtitleGrid.Rows.Clear();if(subtitleEditing==null||subtitleEditing.Document==null)return;var d=subtitleEditing.Document;for(int i=0;i<d.Cues.Count;i++){var c=d.Cues[i];int row=subtitleGrid.Rows.Add(i+1,SubtitleDocument.Stamp(c.Start),SubtitleDocument.Stamp(c.End),c.Text,(c.Reviewed?"Đã duyệt · ":"")+c.Note+(String.IsNullOrEmpty(c.Info)?"":" · "+c.Info));if(!c.Reviewed&&!String.IsNullOrEmpty(c.Note))subtitleGrid.Rows[row].DefaultCellStyle.BackColor=Color.LemonChiffon;else if(c.Reviewed||!String.IsNullOrEmpty(c.Info))subtitleGrid.Rows[row].DefaultCellStyle.BackColor=Color.AliceBlue;}subtitleInfo.Text=d.Cues.Count+" khối · "+SubtitleDocument.Stamp(d.Duration)+" · "+d.Device+" · "+d.ReviewCount+" đoạn cần kiểm tra · "+d.Model;}finally{subtitleLoading=false;}}
 void ReadSubtitleGrid(){if(subtitleEditing==null||subtitleEditing.Document==null)throw new Exception("Chọn file đã nhận dạng để xem/sửa phụ đề.");if(subtitleEditing.SourceStamp!=SubtitleSourceStamp(subtitleEditing.Input))throw new Exception("File nguồn đã thay đổi. Chạy nhận dạng lại trước khi sửa/căn phụ đề.");subtitleGrid.EndEdit();bool anyChanged=false;var items=new List<SubtitleCue>();foreach(DataGridViewRow row in subtitleGrid.Rows){var old=subtitleEditing.Document.Cues[row.Index];string text=Convert.ToString(row.Cells[3].Value);double start=SubtitleDocument.ParseTime(Convert.ToString(row.Cells[1].Value)),end=SubtitleDocument.ParseTime(Convert.ToString(row.Cells[2].Value));bool changed=text!=old.Text||Math.Abs(start-old.Start)>.001||Math.Abs(end-old.End)>.001;anyChanged|=changed;items.Add(new SubtitleCue{Start=start,End=end,Text=text,Note=changed?"Đã sửa · cần nghe/căn lại":old.Note,Info=old.Info,Reviewed=!changed&&old.Reviewed});}var d=new SubtitleDocument{Duration=subtitleEditing.Document.Duration,Model=subtitleEditing.Document.Model,Device=subtitleEditing.Document.Device,Pipeline=subtitleEditing.Document.Pipeline,Audit=subtitleEditing.Document.Audit,Cues=items};d.Validate();subtitleEditing.Document=d;if(anyChanged){subtitleEditing.State="Đã sửa · chưa xuất";subtitleEditing.Profile="";}}
 void SaveSubtitleEdits(){if(subtitleLoading||busy||subtitleEditing==null||subtitleEditing.Document==null||IsDisposed||Disposing)return;try{ReadSubtitleGrid();subtitleEditing.Document.Save(subtitleEditing.Result);subtitleInfo.Text="Đã lưu lời/mốc sửa. Bấm Căn lại lời đã sửa hoặc Xuất SRT để tạo file mới.";}catch(Exception e){subtitleInfo.Text=e.Message;}}
 void SaveSubtitleQueue(){try{Directory.CreateDirectory(SubtitleCache);var x=new XElement("subtitleQueue",new XAttribute("model",subtitleModel.SelectedIndex),new XAttribute("device",subtitleDevice.SelectedIndex),new XAttribute("style",subtitleStyle.SelectedIndex),new XAttribute("track",subtitleTrack.Value));foreach(var j in subtitleQueue)x.Add(new XElement("job",new XAttribute("input",j.Input),new XAttribute("reference",j.Reference),new XAttribute("sourceStamp",j.SourceStamp),new XAttribute("track",j.Track),new XAttribute("result",Path.GetFileName(j.Result)),new XAttribute("output",j.Output),new XAttribute("state",j.State),new XAttribute("error",j.Error),new XAttribute("profile",j.Profile)));StateFiles.Write(Path.Combine(SubtitleHome,"queue.xml"),x);}catch(Exception e){subtitleInfo.Text="Chưa lưu được hàng đợi: "+e.Message;}}
 void RestoreSubtitleQueue(){try{var x=StateFiles.Read(Path.Combine(SubtitleHome,"queue.xml"));if(x==null)return;subtitleModel.SelectedIndex=Math.Max(0,Math.Min(1,StateFiles.I(x,"model")));subtitleDevice.SelectedIndex=Math.Max(0,Math.Min(2,StateFiles.I(x,"device")));subtitleStyle.SelectedIndex=Math.Max(0,Math.Min(1,StateFiles.I(x,"style")));subtitleTrack.Value=Math.Max(1,Math.Min(32,StateFiles.I(x,"track")));foreach(var row in x.Elements("job").Take(500)){string name=StateFiles.S(row,"result");if(Path.GetFileName(name)!=name||name.Length==0)continue;var j=new SubtitleJob{Input=StateFiles.S(row,"input"),Reference=StateFiles.S(row,"reference"),SourceStamp=StateFiles.S(row,"sourceStamp"),Track=Math.Max(0,Math.Min(31,StateFiles.I(row,"track"))),Result=Path.Combine(SubtitleCache,name),Output=StateFiles.S(row,"output"),State=StateFiles.S(row,"state"),Error=StateFiles.S(row,"error"),Profile=StateFiles.S(row,"profile")};if(j.SourceStamp!=SubtitleSourceStamp(j.Input)){j.State="Chờ";j.Document=null;}else if(File.Exists(j.Result))try{j.Document=SubtitleDocument.Load(j.Result);}catch{}if(j.Document!=null&&(j.State=="Xong"||j.State.StartsWith("Đã xuất")))j.State=j.Document.CompletionState;if(j.State=="Đang chạy"||j.State=="Đã dừng"||((j.State=="Xong"||j.State.StartsWith("Đã xuất"))&&(!File.Exists(j.Output)||j.Document==null||j.Document.Pipeline!="v148-verified-1")))j.State="Chờ";subtitleQueue.Add(j);}RefreshSubtitleJobs();}catch(Exception e){subtitleInfo.Text="Không mở được hàng đợi cũ: "+e.Message;}}
 void AttachSubtitleText(){if(busy)return;try{if(subtitleEditing==null)throw new Exception("Chọn một file trong hàng đợi trước khi gắn TXT.");var j=subtitleEditing;if(!String.IsNullOrEmpty(j.Reference)){j.Reference="";j.State="Chờ";j.Error="";RefreshSubtitleJobs();subtitleInfo.Text="Đã bỏ TXT. Lần chạy sau nhận dạng trực tiếp từ âm thanh.";return;}using(var d=new OpenFileDialog{Filter="Lời đọc đúng với âm thanh|*.txt",Title="Chọn TXT lời gốc của file đang chọn"})if(d.ShowDialog()==DialogResult.OK){j.Reference=d.FileName;j.State="Chờ";j.Error="";RefreshSubtitleJobs();subtitleInfo.Text="Đã gắn "+Path.GetFileName(j.Reference)+". TXT phải khớp lời đọc; bấm lại nút để bỏ TXT.";}}catch(Exception e){Error(e);}}
 string SubtitleProfile(SubtitleJob j,string model,bool compact){return "v148-verified-1|"+model+"|"+compact+"|"+j.Track+"|"+j.Reference+"|"+(String.IsNullOrEmpty(j.Reference)?"":SubtitleSourceStamp(j.Reference));}
 bool SubtitleCompleted(SubtitleJob j){return j.Document!=null&&(j.State=="Xong"||j.State.StartsWith("Đã xuất"));}
 void ApproveSubtitleCue(){if(busy)return;try{ReadSubtitleGrid();int row=subtitleGrid.CurrentRow==null?0:subtitleGrid.CurrentRow.Index;var j=subtitleEditing;j.Document.Cues[row].Reviewed=!j.Document.Cues[row].Reviewed;j.Document.Save(j.Result);if(j.State!="Đã sửa · chưa xuất")j.State=j.Document.CompletionState;RefreshSubtitleJobs();if(row<subtitleGrid.Rows.Count)subtitleGrid.CurrentCell=subtitleGrid.Rows[row].Cells[3];status.Text="Đã lưu trạng thái duyệt khối "+(row+1)+".";}catch(Exception e){Error(e);}}
 void SetSubtitleBusy(bool value){if(subtitleOptions==null)return;subtitleOptions.Enabled=subtitleButtons.Enabled=subtitleJobs.Enabled=!value;subtitleGrid.ReadOnly=value;}void CancelTasks(){if(active!=null)active.Cancel();if(subtitleProcess!=null)subtitleProcess.Cancel();}
 void SubtitleNotify(int p,string message){if(IsDisposed||!IsHandleCreated)return;BeginInvoke((Action)(()=>{if(IsDisposed)return;progress.Value=Math.Max(0,Math.Min(100,p));status.Text=message;subtitleInfo.Text=message;}));}
 void RequireSubtitleRuntime(){if(Environment.OSVersion.Platform==PlatformID.Win32NT&&!File.Exists(SubtitlePython))throw new Exception("Bấm Cài bộ phụ đề trong tab MP4/MP3 → SRT. Lần đầu cần mạng; sau đó chạy offline.");}
 string SubtitleArgs(string command,SubtitleJob j,string output,string model,string device,bool compact){string a=command+" --home "+KokoroEngine.Q(SubtitleHome)+" --model "+model+" --device "+device;if(j!=null)a+=" --input "+KokoroEngine.Q(j.Input)+" --track "+j.Track+" --output "+KokoroEngine.Q(output)+" --ffmpeg "+KokoroEngine.Q(Tempo.Executable(root))+" --cache "+KokoroEngine.Q(Path.Combine(SubtitleHome,"cache"))+(compact?" --compact":"")+(command=="run"&&!String.IsNullOrEmpty(j.Reference)?" --reference "+KokoroEngine.Q(j.Reference):"");return a;}
 async Task SetupSubtitles(){if(busy)return;string model=SubtitleModelKey;try{subtitleProcess=new SubtitleProcess();SetBusy(true);status.Text="Cài bộ phụ đề riêng; có thể bấm Dừng tác vụ. Lần đầu tải vài GB.";var worker=subtitleProcess;await Task.Run(()=>worker.Run(ExternalSpeech.Python(root),SubtitleScript("setup_asr.py"),"--home "+KokoroEngine.Q(SubtitleHome)+" --model "+model,SubtitleNotify));status.Text="Đã cài bộ phụ đề "+model+"; các lần tạo SRT sau chạy offline.";}catch(OperationCanceledException){status.Text="Đã dừng cài. Bấm Cài bộ phụ đề để bổ sung phần còn thiếu.";}catch(Exception e){Error(e);}finally{if(subtitleProcess!=null)subtitleProcess.Dispose();subtitleProcess=null;SetBusy(false);}}
 async Task ProbeSubtitles(){if(busy)return;try{RequireSubtitleRuntime();string args=SubtitleArgs("probe",null,null,SubtitleModelKey,SubtitleDeviceKey,false);subtitleProcess=new SubtitleProcess();SetBusy(true);var worker=subtitleProcess;await Task.Run(()=>worker.Run(SubtitlePython,SubtitleScript("asr_worker.py"),args,SubtitleNotify));}catch(OperationCanceledException){status.Text="Đã dừng kiểm tra phụ đề.";}catch(Exception e){Error(e);}finally{if(subtitleProcess!=null)subtitleProcess.Dispose();subtitleProcess=null;SetBusy(false);}}
 async Task RunSubtitleQueue(){if(busy)return;try{if(subtitleQueue.Count==0)throw new Exception("Thêm MP4/MP3 trước khi tạo SRT.");if(subtitleEditing!=null&&subtitleEditing.Document!=null&&subtitleEditing.SourceStamp==SubtitleSourceStamp(subtitleEditing.Input)){ReadSubtitleGrid();subtitleEditing.Document.Save(subtitleEditing.Result);}RequireSubtitleRuntime();string model=SubtitleModelKey,device=SubtitleDeviceKey;bool compact=subtitleStyle.SelectedIndex==1,skip=subtitleSkip.Checked;SetBusy(true);if(player!=null)player.Stop();
  foreach(var j in subtitleQueue){if(skip&&SubtitleCompleted(j)&&j.Document.Pipeline=="v148-verified-1"&&j.Profile==SubtitleProfile(j,model,compact)&&File.Exists(j.Output)&&j.SourceStamp==SubtitleSourceStamp(j.Input))continue;j.SourceStamp=SubtitleSourceStamp(j.Input);j.State="Đang chạy";j.Error="";RefreshSubtitleJobs();subtitleProcess=new SubtitleProcess();var worker=subtitleProcess;string result=j.Result+".new.xml",args=SubtitleArgs("run",j,result,model,device,compact);try{await Task.Run(()=>worker.Run(SubtitlePython,SubtitleScript("asr_worker.py"),args,(p,m)=>SubtitleNotify(p,Path.GetFileName(j.Input)+" · "+m)));if(j.SourceStamp!=SubtitleSourceStamp(j.Input))throw new IOException("File nguồn thay đổi trong lúc chạy. Chạy lại để nhận dạng bản mới.");var d=SubtitleDocument.Load(result);d.Save(j.Result);j.Document=d;j.Output=d.ExportBeside(j.Input);j.State=d.CompletionState;j.Profile=SubtitleProfile(j,model,compact);}catch(OperationCanceledException){j.State="Đã dừng";break;}catch(Exception e){j.State="Lỗi";j.Error=e.Message;try{Directory.CreateDirectory(Path.Combine(stateDir,"logs"));File.AppendAllText(Path.Combine(stateDir,"logs","subtitle-errors.log"),DateTime.Now.ToString("s")+" "+j.Input+"\r\n"+e+"\r\n");}catch{}}finally{worker.Dispose();subtitleProcess=null;try{File.Delete(result);}catch{}RefreshSubtitleJobs();}}
  status.Text="Phụ đề: "+subtitleQueue.Count(j=>SubtitleCompleted(j))+" đã xuất · "+subtitleQueue.Count(j=>SubtitleCompleted(j)&&j.Document.ReviewCount>0)+" file cần duyệt · "+subtitleQueue.Count(j=>j.State=="Lỗi")+" lỗi · "+subtitleQueue.Count(j=>j.State=="Đã dừng")+" dừng. SRT lưu cạnh file gốc.";
 }catch(Exception e){Error(e);}finally{if(subtitleProcess!=null)subtitleProcess.Dispose();subtitleProcess=null;SetBusy(false);SaveSubtitleQueue();}}
 void ExportSubtitleEdits(){if(busy)return;try{ReadSubtitleGrid();subtitleEditing.Document.Save(subtitleEditing.Result);subtitleEditing.Output=subtitleEditing.Document.ExportBeside(subtitleEditing.Input);subtitleEditing.State=subtitleEditing.Document.CompletionState;subtitleEditing.Error="";RefreshSubtitleJobs();status.Text="Đã xuất "+subtitleEditing.Output;}catch(Exception e){Error(e);}}
 async Task RealignSubtitle(){if(busy)return;string draft=null,result=null;try{ReadSubtitleGrid();RequireSubtitleRuntime();var j=subtitleEditing;draft=j.Result+".draft.xml";result=j.Result+".aligned.xml";j.Document.Save(draft);string args=SubtitleArgs("align",j,result,SubtitleModelKey,SubtitleDeviceKey,subtitleStyle.SelectedIndex==1)+" --draft "+KokoroEngine.Q(draft);subtitleProcess=new SubtitleProcess();var worker=subtitleProcess;SetBusy(true);await Task.Run(()=>worker.Run(SubtitlePython,SubtitleScript("asr_worker.py"),args,SubtitleNotify));var d=SubtitleDocument.Load(result);d.Save(j.Result);j.Document=d;j.Output=d.ExportBeside(j.Input);j.State=d.CompletionState;j.Profile=SubtitleProfile(j,SubtitleModelKey,subtitleStyle.SelectedIndex==1);j.Error="";RefreshSubtitleJobs();status.Text="Đã căn lại và xuất SRT mới: "+j.Output;}catch(OperationCanceledException){status.Text="Đã dừng căn; bản phụ đề cũ được giữ.";}catch(Exception e){Error(e);}finally{if(subtitleProcess!=null)subtitleProcess.Dispose();subtitleProcess=null;SetBusy(false);foreach(string f in new[]{draft,result})if(f!=null)try{File.Delete(f);}catch{}}}
 async Task ListenSubtitle(){if(busy)return;try{ReadSubtitleGrid();RequireSubtitleRuntime();var j=subtitleEditing;int index=subtitleGrid.CurrentRow==null?0:subtitleGrid.CurrentRow.Index;var c=j.Document.Cues[index];string output=Path.Combine(SubtitleCache,"listen.wav"),args=SubtitleArgs("preview",j,output,SubtitleModelKey,SubtitleDeviceKey,false)+" --start "+Math.Max(0,c.Start-.15).ToString("R",System.Globalization.CultureInfo.InvariantCulture)+" --end "+Math.Min(j.Document.Duration,c.End+.2).ToString("R",System.Globalization.CultureInfo.InvariantCulture);if(player!=null)player.Dispose();player=null;subtitleProcess=new SubtitleProcess();var worker=subtitleProcess;SetBusy(true);await Task.Run(()=>worker.Run(SubtitlePython,SubtitleScript("asr_worker.py"),args,SubtitleNotify));Play(output);status.Text="Đang phát âm thanh gốc của khối "+(index+1)+".";}catch(OperationCanceledException){status.Text="Đã dừng nghe đoạn.";}catch(Exception e){Error(e);}finally{if(subtitleProcess!=null)subtitleProcess.Dispose();subtitleProcess=null;SetBusy(false);}}
}}
